// AuthServiceClient is a client for the nagi.v1.AuthService service.
type AuthServiceClient interface {
	// 开启了两步验证时，没带验证码会返回 failed_precondition，界面据此显示验证码输入框。
	Login(context.Context, *connect.Request[v1.LoginRequest]) (*connect.Response[v1.LoginResponse], error)
	Logout(context.Context, *connect.Request[v1.LogoutRequest]) (*connect.Response[v1.LogoutResponse], error)
	Me(context.Context, *connect.Request[v1.MeRequest]) (*connect.Response[v1.MeResponse], error)
	// 高权限确认：打开节点终端、访问节点文件前再验证一次身份（见 docs/node-access.md#权限）。
	Elevate(context.Context, *connect.Request[v1.ElevateRequest]) (*connect.Response[v1.ElevateResponse], error)
	// 手机确认（见 docs/android.md#手机确认）：网页发起，成员在手机 App 上用指纹、面容或锁屏密码确认。
	// 高权限确认：发起后轮询 GetPhoneApproval，手机确认后这个会话算做过高权限确认（给自己留登录凭据的操作不认）。
	BeginPhoneApproval(context.Context, *connect.Request[v1.BeginPhoneApprovalRequest]) (*connect.Response[v1.PhoneApproval], error)
	GetPhoneApproval(context.Context, *connect.Request[v1.GetPhoneApprovalRequest]) (*connect.Response[v1.GetPhoneApprovalResponse], error)
	// 登录的第二步：密码对了、开了两步验证的账号可以在手机上确认，代替验证码。不用登录。
	// 发起后轮询 CompleteLoginApproval，手机确认后它返回会话 cookie。
	BeginLoginApproval(context.Context, *connect.Request[v1.BeginLoginApprovalRequest]) (*connect.Response[v1.PhoneApproval], error)
	CompleteLoginApproval(context.Context, *connect.Request[v1.CompleteLoginApprovalRequest]) (*connect.Response[v1.CompleteLoginApprovalResponse], error)
	// 修改密码。成功后其他地方的登录全部失效。
	ChangePassword(context.Context, *connect.Request[v1.ChangePasswordRequest]) (*connect.Response[v1.ChangePasswordResponse], error)
	// 保存界面语言。浏览器优先用自己记住的选择，没有时（例如换了设备）用这里保存的。
	SetLanguage(context.Context, *connect.Request[v1.SetLanguageRequest]) (*connect.Response[v1.SetLanguageResponse], error)
	// 保存自己的个人资料（显示名称和头像），整份覆盖。
	UpdateProfile(context.Context, *connect.Request[v1.UpdateProfileRequest]) (*connect.Response[v1.UpdateProfileResponse], error)
	// OAuth 授权页（见 docs/mcp.md#oauth）：检查授权请求，返回客户端的名称和回调地址的域名。
	GetOAuthRequest(context.Context, *connect.Request[v1.OAuthRequest]) (*connect.Response[v1.GetOAuthRequestResponse], error)
	// 成员在授权页上允许或拒绝，返回浏览器要转去的回调地址（带授权码或者错误）。
	ApproveOAuth(context.Context, *connect.Request[v1.ApproveOAuthRequest]) (*connect.Response[v1.ApproveOAuthResponse], error)
	// 会话加固（见 docs/panel.md#会话）：登录后登记会话密钥的公钥；响应头里出现挑战时用私钥签名，换发新令牌。
	RegisterSessionKey(context.Context, *connect.Request[v1.RegisterSessionKeyRequest]) (*connect.Response[v1.RegisterSessionKeyResponse], error)
	RotateSession(context.Context, *connect.Request[v1.RotateSessionRequest]) (*connect.Response[v1.RotateSessionResponse], error)
	// 会话被要求重新验证时：开了两步验证的输验证码，没开的输密码。连续 3 次失败退出这个会话。
	Reverify(context.Context, *connect.Request[v1.ReverifyRequest]) (*connect.Response[v1.ReverifyResponse], error)
	// 用通行密钥登录（见 docs/panel.md#通行密钥）：先取挑战，浏览器签名后提交。
	BeginPasskeyLogin(context.Context, *connect.Request[v1.BeginPasskeyLoginRequest]) (*connect.Response[v1.PasskeyChallenge], error)
	PasskeyLogin(context.Context, *connect.Request[v1.PasskeyLoginRequest]) (*connect.Response[v1.LoginResponse], error)
	// 自己的项目页排序（见 docs/panel.md#分组和标签）：排序方式和自定义顺序，存在面板上，每个成员各自一份。
	GetProjectOrder(context.Context, *connect.Request[v1.GetProjectOrderRequest]) (*connect.Response[v1.ProjectOrder], error)
	// 整份覆盖。
	SetProjectOrder(context.Context, *connect.Request[v1.ProjectOrder]) (*connect.Response[v1.SetProjectOrderResponse], error)
	// 自己的节点页排序，同项目页。
	GetNodeOrder(context.Context, *connect.Request[v1.GetNodeOrderRequest]) (*connect.Response[v1.NodeOrder], error)
	SetNodeOrder(context.Context, *connect.Request[v1.NodeOrder]) (*connect.Response[v1.SetNodeOrderResponse], error)
	// 添加手机（见 docs/android.md#扫码）：生成配对码和二维码内容。要先用密码或验证码做高权限确认。
	CreateAppPairing(context.Context, *connect.Request[v1.CreateAppPairingRequest]) (*connect.Response[v1.CreateAppPairingResponse], error)
	// 配对码有没有用掉，网页每 2 秒查一次，直到添加完成或过期。
	GetAppPairing(context.Context, *connect.Request[v1.GetAppPairingRequest]) (*connect.Response[v1.GetAppPairingResponse], error)
}

