// NodeServiceClient is a client for the nagi.v1.NodeService service.
type NodeServiceClient interface {
	ListNodes(context.Context, *connect.Request[v1.ListNodesRequest]) (*connect.Response[v1.ListNodesResponse], error)
	// ---- 节点文件（见 docs/node-access.md）：只有管理员，要先做高权限确认 ----
	ListNodeDir(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ListNodeDirResponse], error)
	ReadNodeFile(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ReadNodeFileResponse], error)
	WriteNodeFile(context.Context, *connect.Request[v1.WriteNodeFileRequest]) (*connect.Response[v1.WriteNodeFileResponse], error)
	DeleteNodeFile(context.Context, *connect.Request[v1.DeleteNodeFileRequest]) (*connect.Response[v1.NodeFileOpResponse], error)
	CreateNodeDir(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.NodeFileOpResponse], error)
	ListNodeFileBackups(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ListNodeFileBackupsResponse], error)
	RestoreNodeFileBackup(context.Context, *connect.Request[v1.RestoreNodeFileBackupRequest]) (*connect.Response[v1.WriteNodeFileResponse], error)
	RenameNodeFile(context.Context, *connect.Request[v1.NodeTransferRequest]) (*connect.Response[v1.FileOpResult], error)
	MoveNodeFiles(context.Context, *connect.Request[v1.NodeTransferRequest]) (*connect.ServerStreamForClient[v1.FileOpEvent], error)
	CopyNodeFiles(context.Context, *connect.Request[v1.NodeTransferRequest]) (*connect.ServerStreamForClient[v1.FileOpEvent], error)
	CompressNodeFiles(context.Context, *connect.Request[v1.NodeCompressRequest]) (*connect.ServerStreamForClient[v1.FileOpEvent], error)
	ExtractNodeFile(context.Context, *connect.Request[v1.NodeExtractRequest]) (*connect.ServerStreamForClient[v1.FileOpEvent], error)
	ListNodeDirSizes(context.Context, *connect.Request[v1.NodeDirSizesRequest]) (*connect.Response[v1.DirSizesResponse], error)
	// 节点信任的面板列表。
	ListNodePanels(context.Context, *connect.Request[v1.ListNodePanelsRequest]) (*connect.Response[v1.ListNodePanelsResponse], error)
	// 移交（见 docs/control-plane.md）：用另一个面板的接入码，让这些节点加入那个面板，随后把本面板从节点上移除，
	// 忘记这些节点和它们上面的项目。按整个项目：项目相关的节点（容器所在、顶替、备份、见证）必须都在里面。
	HandoverNodes(context.Context, *connect.Request[v1.HandoverNodesRequest]) (*connect.Response[v1.HandoverNodesResponse], error)
	// 从节点的信任列表移除一个面板。移除的是本面板时，本面板同时忘记这个节点。
	RemoveNodePanel(context.Context, *connect.Request[v1.RemoveNodePanelRequest]) (*connect.Response[v1.RemoveNodePanelResponse], error)
	// 节点上保存的副本（作为备份节点或热备）。in_use 为 false 的是已经没有容器使用的副本，可以删除。
	ListNodeReplicas(context.Context, *connect.Request[v1.NodeRef]) (*connect.Response[v1.ListNodeReplicasResponse], error)
	DeleteNodeReplica(context.Context, *connect.Request[v1.DeleteNodeReplicaRequest]) (*connect.Response[v1.DeleteNodeReplicaResponse], error)
	// 节点的 mesh 状态。
	GetNodeMesh(context.Context, *connect.Request[v1.GetNodeMeshRequest]) (*connect.Response[v1.MeshStatus], error)
	// 让节点经 mesh 连一下某个成员。
	PingNodeMesh(context.Context, *connect.Request[v1.PingNodeMeshRequest]) (*connect.Response[v1.MeshPingResponse], error)
	// 让节点经 mesh 和某个成员测速（见 docs/mesh.md#测速）。只有管理员能用。
	TestNodeMeshSpeed(context.Context, *connect.Request[v1.PingNodeMeshRequest]) (*connect.Response[v1.MeshSpeedResponse], error)
	// 修改节点的组网设置（关闭 QUIC 快速通道）。
	SetNodeMeshOptions(context.Context, *connect.Request[v1.SetNodeMeshOptionsRequest]) (*connect.Response[v1.MeshOptions], error)
	// 面板自己的 mesh 状态。
	GetPanelMesh(context.Context, *connect.Request[v1.GetPanelMeshRequest]) (*connect.Response[v1.MeshStatus], error)
	// 把节点升级到面板提供的版本（面板自带的节点随面板升级，不能单独升级）。在后台进行，进度用 GetUpdateStatus 查。
	UpgradeNode(context.Context, *connect.Request[v1.UpgradeNodeRequest]) (*connect.Response[v1.UpgradeResponse], error)
	// 把所有落后于面板的节点逐个升级到面板的版本：下载阶段失败的记下原因接着升下一个，替换后没回来就停下。
	// 在后台进行，进度用 GetUpdateStatus 查。
	UpgradeAllNodes(context.Context, *connect.Request[v1.UpgradeAllNodesRequest]) (*connect.Response[v1.UpgradeAllNodesResponse], error)
	// 取消升级：排队的不再升级，下载中的停止下载；已经替换、正在重启的不能取消。
	CancelNodeUpgrade(context.Context, *connect.Request[v1.CancelNodeUpgradeRequest]) (*connect.Response[v1.CancelNodeUpgradeResponse], error)
	// 节点的镜像加速地址。
	GetNodeMirrors(context.Context, *connect.Request[v1.NodeRef]) (*connect.Response[v1.Mirrors], error)
	SetNodeMirrors(context.Context, *connect.Request[v1.SetNodeMirrorsRequest]) (*connect.Response[v1.Mirrors], error)
	// 立即清理节点上每个容器的快照仓库，回收没有快照用到的数据。只有管理员能用。
	ReclaimNodeSnapshots(context.Context, *connect.Request[v1.NodeRef]) (*connect.ServerStreamForClient[v1.DeployEvent], error)
	// 节点的项目根目录：容器目录默认是 <项目根目录>/<项目名的拼音>/<容器名>。
	SetNodeProjectsRoot(context.Context, *connect.Request[v1.SetNodeProjectsRootRequest]) (*connect.Response[v1.SetProjectsRootResponse], error)
	// 节点保存副本的默认目录，把在默认目录里的副本移过去（见 docs/snapshot.md#副本的存放位置）。只有管理员能用，要先做高权限确认。
	SetNodeReplicaDir(context.Context, *connect.Request[v1.SetNodeReplicaDirRequest]) (*connect.ServerStreamForClient[v1.DeployEvent], error)
	// 生成一条添加节点的安装命令，里面带一次性令牌（1 小时内有效）。
	CreateEnrollCommand(context.Context, *connect.Request[v1.CreateEnrollCommandRequest]) (*connect.Response[v1.CreateEnrollCommandResponse], error)
	QueryNodeMetrics(context.Context, *connect.Request[v1.QueryNodeMetricsRequest]) (*connect.Response[v1.QueryMetricsResponse], error)
	// 节点的磁盘占用明细（只读）。只有管理员能看：内容涉及节点上所有项目。
	GetNodeStorage(context.Context, *connect.Request[v1.NodeRef]) (*connect.Response[v1.NodeStorage], error)
	// 移除节点：面板忘记它并拒绝它再连接。节点上还有容器时拒绝。
	RemoveNode(context.Context, *connect.Request[v1.RemoveNodeRequest]) (*connect.Response[v1.RemoveNodeResponse], error)
	// 批准用接入码加入的节点。接入码可以多次使用、还会经过别的面板转交，泄露了别人也能用它加入节点，
	// 所以这样加入的节点要管理员确认。
	ApproveNode(context.Context, *connect.Request[v1.ApproveNodeRequest]) (*connect.Response[v1.ApproveNodeResponse], error)
	// 修改节点在面板上显示的名称（加入时是节点的主机名）。只存在面板上，不改节点本机的主机名。
	RenameNode(context.Context, *connect.Request[v1.RenameNodeRequest]) (*connect.Response[v1.RenameNodeResponse], error)
	// 把节点上面板不认识的容器按节点的缓存加入项目（见 Node.unknown_containers）。
	AdoptNodeContainer(context.Context, *connect.Request[v1.AdoptNodeContainerRequest]) (*connect.Response[v1.AdoptNodeContainerResponse], error)
	// 以节点为准重建项目（见 Node.stale_projects）：删掉面板上的记录，按节点缓存拼回。
	AdoptStaleProject(context.Context, *connect.Request[v1.AdoptStaleProjectRequest]) (*connect.Response[v1.AdoptStaleProjectResponse], error)
	// 确认（或放弃）从节点缓存拼回的顶替设置和备份节点（见 Container.pending_ha）。
	ConfirmPendingHA(context.Context, *connect.Request[v1.ConfirmPendingHARequest]) (*connect.Response[v1.ConfirmPendingHAResponse], error)
	// 修改节点的告警规则（内存、磁盘、离线、证书）。
	SetNodeAlertRules(context.Context, *connect.Request[v1.SetNodeAlertRulesRequest]) (*connect.Response[v1.SetNodeAlertRulesResponse], error)
	// 预览节点上一个现有的 compose 目录能不能导入（见 docs/agent.md#现有目录）。只有管理员能用，要先确认身份。
	InspectComposeDir(context.Context, *connect.Request[v1.NodeFileRef]) (*connect.Response[v1.ComposeDirPreview], error)
	// 替换节点的标签（见 docs/panel.md#分组和标签）。
	SetNodeTags(context.Context, *connect.Request[v1.SetNodeTagsRequest]) (*connect.Response[v1.SetNodeTagsResponse], error)
	// 重命名或删除标签（new_name 为空），所有节点和成员的访问范围一起改。
	RenameNodeTag(context.Context, *connect.Request[v1.RenameLabelRequest]) (*connect.Response[v1.RenameLabelResponse], error)
	// 把节点放进分组（见 docs/panel.md#分组和标签）。节点分组只用来整理节点页，不影响访问范围。
	SetNodeGroup(context.Context, *connect.Request[v1.SetNodeGroupRequest]) (*connect.Response[v1.SetNodeGroupResponse], error)
	// 重命名或删除节点分组（new_name 为空），所有节点一起改。
	RenameNodeGroup(context.Context, *connect.Request[v1.RenameLabelRequest]) (*connect.Response[v1.RenameLabelResponse], error)
	// 加入或退出中转池（见 docs/mesh.md#中转池）：开了就同意这个节点为别的节点承担性能中转，存在面板上，立即下发。
	SetNodeRelayPool(context.Context, *connect.Request[v1.SetNodeRelayPoolRequest]) (*connect.Response[v1.SetNodeRelayPoolResponse], error)
	// 隔离节点（见 docs/mesh.md#隔离）：立即从所有节点的 mesh 成员里去掉，撤销它的项目放行，停止为它中转。
	// 只有管理员能用，要先做高权限确认并输入节点名。
	IsolateNode(context.Context, *connect.Request[v1.IsolateNodeRequest]) (*connect.Response[v1.IsolateNodeResponse], error)
	UnisolateNode(context.Context, *connect.Request[v1.IsolateNodeRequest]) (*connect.Response[v1.IsolateNodeResponse], error)
	// 节点镜像（见 docs/agent.md#节点镜像）：只有管理员能用，访问令牌不能用。
	ListNodeImages(context.Context, *connect.Request[v1.NodeRef]) (*connect.Response[v1.NodeImages], error)
	DeleteNodeImages(context.Context, *connect.Request[v1.DeleteNodeImagesRequest]) (*connect.Response[v1.DeleteImagesResponse], error)
	PruneNodeImages(context.Context, *connect.Request[v1.PruneNodeImagesRequest]) (*connect.Response[v1.PruneImagesResponse], error)
	// 浏览器断开（取消）时停止拉取。
	PullNodeImage(context.Context, *connect.Request[v1.PullNodeImageRequest]) (*connect.ServerStreamForClient[v1.ImagePullEvent], error)
}

