// SettingsServiceClient is a client for the nagi.v1.SettingsService service.
type SettingsServiceClient interface {
	GetSettings(context.Context, *connect.Request[v1.GetSettingsRequest]) (*connect.Response[v1.GetSettingsResponse], error)
	UpdateSettings(context.Context, *connect.Request[v1.UpdateSettingsRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 绑定面板域名（为空表示取消），自动申请正式证书。节点的控制连接和安装命令仍然用 IP:端口 + 公钥指纹。
	SetPanelDomain(context.Context, *connect.Request[v1.SetPanelDomainApiRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 修改面板名称（App 的顶部栏、解锁页和面板列表用它）。为空时恢复默认（面板机器的主机名）。
	SetPanelName(context.Context, *connect.Request[v1.SetPanelNameRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	// 打开或关闭 mesh 自动切路（全局，默认关闭，见 docs/mesh.md#自动切路），立即下发给各节点。只有管理员能用。
	SetMeshAutoRoute(context.Context, *connect.Request[v1.SetMeshAutoRouteRequest]) (*connect.Response[v1.UpdateSettingsResponse], error)
	GetAlertConfig(context.Context, *connect.Request[v1.GetAlertConfigRequest]) (*connect.Response[v1.GetAlertConfigResponse], error)
	UpdateAlertConfig(context.Context, *connect.Request[v1.UpdateAlertConfigRequest]) (*connect.Response[v1.UpdateAlertConfigResponse], error)
	// 用面板发一条测试消息到某个渠道。
	TestAlertChannel(context.Context, *connect.Request[v1.TestAlertChannelRequest]) (*connect.Response[v1.TestAlertChannelResponse], error)
	// 生成接入码：其他面板用它把节点交给本面板。1 小时内可以给多个节点用。
	CreateInvite(context.Context, *connect.Request[v1.CreateInviteRequest]) (*connect.Response[v1.CreateInviteResponse], error)
	// 还在有效期内的接入码。
	ListInvites(context.Context, *connect.Request[v1.ListInvitesRequest]) (*connect.Response[v1.ListInvitesResponse], error)
	// 提前作废接入码。
	RevokeInvite(context.Context, *connect.Request[v1.RevokeInviteRequest]) (*connect.Response[v1.RevokeInviteResponse], error)
	// 主备面板（见 docs/standby.md）：生成配对码、列出和移除备用面板；备用面板上返回自己的同步状态。
	CreateStandbyCode(context.Context, *connect.Request[v1.CreateStandbyCodeRequest]) (*connect.Response[v1.CreateStandbyCodeResponse], error)
	GetStandbys(context.Context, *connect.Request[v1.GetStandbysRequest]) (*connect.Response[v1.GetStandbysResponse], error)
	RemoveStandby(context.Context, *connect.Request[v1.RemoveStandbyRequest]) (*connect.Response[v1.RemoveStandbyResponse], error)
	// 把本面板（备用面板）提升为主面板：任期加一，面板按主面板重新启动（见 docs/standby.md#提升）。
	PromoteStandby(context.Context, *connect.Request[v1.PromoteStandbyRequest]) (*connect.Response[v1.PromoteStandbyResponse], error)
	// 检查 GitHub Release 上有没有比本面板新的版本（见 docs/panel.md#更新面板）。
	CheckPanelUpdate(context.Context, *connect.Request[v1.CheckPanelUpdateRequest]) (*connect.Response[v1.CheckPanelUpdateResponse], error)
	// 把本面板更新到最新发布的版本：在后台下载并核对后替换可执行文件，然后原地重启。备用面板上也可以用。
	UpdatePanel(context.Context, *connect.Request[v1.UpdatePanelRequest]) (*connect.Response[v1.UpdatePanelResponse], error)
	// 本面板到最新版本之间各版本的更新日志，按界面语言取（见 docs/panel.md#更新面板）。
	GetPanelReleaseNotes(context.Context, *connect.Request[v1.GetPanelReleaseNotesRequest]) (*connect.Response[v1.GetPanelReleaseNotesResponse], error)
	// 面板和节点的更新进度。记在面板上，刷新页面和面板重启后都还在（见 docs/panel.md#更新状态）。
	GetUpdateStatus(context.Context, *connect.Request[v1.GetUpdateStatusRequest]) (*connect.Response[v1.GetUpdateStatusResponse], error)
	// 账号安全：两步验证和安全入口。
	GetSecurity(context.Context, *connect.Request[v1.GetSecurityRequest]) (*connect.Response[v1.Security], error)
	// 开始设置两步验证：返回密钥和验证器 App 扫码用的地址，10 分钟内用 EnableTOTP 确认。
	BeginTOTP(context.Context, *connect.Request[v1.BeginTOTPRequest]) (*connect.Response[v1.BeginTOTPResponse], error)
	EnableTOTP(context.Context, *connect.Request[v1.EnableTOTPRequest]) (*connect.Response[v1.Security], error)
	// 关闭两步验证，需要当前的验证码或者密码。
	DisableTOTP(context.Context, *connect.Request[v1.DisableTOTPRequest]) (*connect.Response[v1.Security], error)
	// 开启（生成新的随机路径）或关闭安全入口。
	SetEntrance(context.Context, *connect.Request[v1.SetEntranceRequest]) (*connect.Response[v1.Security], error)
	// 活动记录：用户的操作和告警，新的在前。
	ListActivity(context.Context, *connect.Request[v1.ListActivityRequest]) (*connect.Response[v1.ListActivityResponse], error)
	// 成员（只有管理员能用）。
	ListUsers(context.Context, *connect.Request[v1.ListUsersRequest]) (*connect.Response[v1.ListUsersResponse], error)
	CreateUser(context.Context, *connect.Request[v1.CreateUserRequest]) (*connect.Response[v1.PanelUser], error)
	// 修改角色、重置密码、清除两步验证、清除通行密钥。重置密码后这个用户已有的登录全部失效；
	// 重置密码和清除两步验证时一并删除通行密钥（见 docs/panel.md#通行密钥）。
	UpdateUser(context.Context, *connect.Request[v1.UpdateUserRequest]) (*connect.Response[v1.UpdateUserResponse], error)
	DeleteUser(context.Context, *connect.Request[v1.DeleteUserRequest]) (*connect.Response[v1.DeleteUserResponse], error)
	// 当前用户自己的登录会话。
	ListSessions(context.Context, *connect.Request[v1.ListSessionsRequest]) (*connect.Response[v1.ListSessionsResponse], error)
	RevokeSession(context.Context, *connect.Request[v1.RevokeSessionRequest]) (*connect.Response[v1.RevokeSessionResponse], error)
	// 访问令牌（见 docs/mcp.md#登录）。user_id 为 0 时是自己的；管理员可以查看、吊销其他成员的。
	ListAccessTokens(context.Context, *connect.Request[v1.ListAccessTokensRequest]) (*connect.Response[v1.ListAccessTokensResponse], error)
	// 生成个人访问令牌，只能给自己生成，要先做高权限确认。
	CreateAccessToken(context.Context, *connect.Request[v1.CreateAccessTokenRequest]) (*connect.Response[v1.CreateAccessTokenResponse], error)
	RevokeAccessToken(context.Context, *connect.Request[v1.RevokeAccessTokenRequest]) (*connect.Response[v1.RevokeAccessTokenResponse], error)
	// 审计日志（见 docs/audit.md）。管理员看全部；操作员和只读成员只看访问范围内项目的记录，不含 IP 和浏览器。
	ListAuditEvents(context.Context, *connect.Request[v1.ListAuditEventsRequest]) (*connect.Response[v1.ListAuditEventsResponse], error)
	// 一条记录的详情，带上级和下级记录。
	GetAuditEvent(context.Context, *connect.Request[v1.GetAuditEventRequest]) (*connect.Response[v1.GetAuditEventResponse], error)
	// 按筛选条件导出 JSON Lines，只有管理员能用。
	ExportAuditEvents(context.Context, *connect.Request[v1.ExportAuditEventsRequest]) (*connect.ServerStreamForClient[v1.ExportAuditEventsChunk], error)
	// 会话设置（「设置 → 安全 → 会话」，见 docs/panel.md#会话），只有管理员能改。
	GetSessionPolicy(context.Context, *connect.Request[v1.GetSessionPolicyRequest]) (*connect.Response[v1.SessionPolicy], error)
	SetSessionPolicy(context.Context, *connect.Request[v1.SessionPolicy]) (*connect.Response[v1.SessionPolicy], error)
	// 回放终端录制（见 docs/audit.md#终端与命令录制）：按块返回 asciicast v2 的内容。只有管理员能用，要先做高权限确认。
	GetRecording(context.Context, *connect.Request[v1.GetRecordingRequest]) (*connect.ServerStreamForClient[v1.RecordingChunk], error)
	// 审计设置（「设置 → 安全」）：终端录制等。关闭录制要先做高权限确认。
	GetAuditSettings(context.Context, *connect.Request[v1.GetAuditSettingsRequest]) (*connect.Response[v1.AuditSettings], error)
	SetAuditSettings(context.Context, *connect.Request[v1.AuditSettings]) (*connect.Response[v1.AuditSettings], error)
	// 向外送目标发一条测试消息。
	TestAuditSink(context.Context, *connect.Request[v1.AuditSink]) (*connect.Response[v1.TestAuditSinkResponse], error)
	// 校验审计日志的哈希链（和 nagi audit verify 一样）。
	VerifyAudit(context.Context, *connect.Request[v1.VerifyAuditRequest]) (*connect.Response[v1.AuditChainStatus], error)
	// 通行密钥（见 docs/panel.md#通行密钥）：开始添加要先做高权限确认，浏览器创建后用 AddPasskey 保存。
	BeginPasskeyRegistration(context.Context, *connect.Request[v1.BeginPasskeyRegistrationRequest]) (*connect.Response[v1.BeginPasskeyRegistrationResponse], error)
	AddPasskey(context.Context, *connect.Request[v1.AddPasskeyRequest]) (*connect.Response[v1.Security], error)
	DeletePasskey(context.Context, *connect.Request[v1.DeletePasskeyRequest]) (*connect.Response[v1.Security], error)
	// 管理员登录地址（见 docs/panel.md#管理员登录地址）：只有管理员能看和改，保存时当前地址必须在列表里。
	GetAdminNetworks(context.Context, *connect.Request[v1.GetAdminNetworksRequest]) (*connect.Response[v1.AdminNetworks], error)
	SetAdminNetworks(context.Context, *connect.Request[v1.AdminNetworks]) (*connect.Response[v1.AdminNetworks], error)
	// 角色（见 docs/panel.md#成员和角色）：管理员是固定的，不能编辑；操作员、只读是预置的，可以编辑；可以新建。
	// 正在使用的角色不能删除。要「成员」权限；不是管理员时只能授予自己有的权限。
	ListRoles(context.Context, *connect.Request[v1.ListRolesRequest]) (*connect.Response[v1.ListRolesResponse], error)
	CreateRole(context.Context, *connect.Request[v1.CreateRoleRequest]) (*connect.Response[v1.Role], error)
	UpdateRole(context.Context, *connect.Request[v1.UpdateRoleRequest]) (*connect.Response[v1.Role], error)
	DeleteRole(context.Context, *connect.Request[v1.DeleteRoleRequest]) (*connect.Response[v1.DeleteRoleResponse], error)
}

