// ProjectServiceHandler is an implementation of the nagi.v1.ProjectService service.
type ProjectServiceHandler interface {
	ListProjects(context.Context, *connect.Request[v1.ListProjectsRequest]) (*connect.Response[v1.ListProjectsResponse], error)
	// 新建项目，可以同时带上第一个容器（只保存，不部署）。
	CreateProject(context.Context, *connect.Request[v1.CreateProjectRequest]) (*connect.Response[v1.Project], error)
	GetProject(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.ProjectSummary], error)
	// 修改项目设置：名称、网络名、快照间隔、内部端口，立即生效。共享变量不在这里改。
	UpdateProjectSettings(context.Context, *connect.Request[v1.UpdateProjectSettingsRequest]) (*connect.Response[v1.Project], error)
	// 把项目放进分组（group 为空表示移出，见 docs/panel.md#分组和标签）。会改变成员的访问范围，只有管理员能用。
	SetProjectGroup(context.Context, *connect.Request[v1.SetProjectGroupRequest]) (*connect.Response[v1.Project], error)
	// 重命名或删除分组（new_name 为空），成员的访问范围一起改。只有管理员能用。
	RenameProjectGroup(context.Context, *connect.Request[v1.RenameLabelRequest]) (*connect.Response[v1.RenameLabelResponse], error)
	// 替换项目的标签（见 docs/panel.md#分组和标签）。项目标签只用来整理项目页，不影响访问范围。
	SetProjectTags(context.Context, *connect.Request[v1.SetProjectTagsRequest]) (*connect.Response[v1.Project], error)
	// 重命名或删除项目标签（new_name 为空），所有项目一起改。
	RenameProjectTag(context.Context, *connect.Request[v1.RenameLabelRequest]) (*connect.Response[v1.RenameLabelResponse], error)
	// 保存共享变量的草稿，返回引用了改动变量的容器（部署共享变量时默认一起部署）。
	SaveSharedEnv(context.Context, *connect.Request[v1.SaveSharedEnvRequest]) (*connect.Response[v1.SaveSharedEnvResponse], error)
	DiscardSharedEnv(context.Context, *connect.Request[v1.ProjectRevisionRef]) (*connect.Response[v1.Project], error)
	// 删除项目：删除所有容器，容器目录默认保留。
	DeleteProject(context.Context, *connect.Request[v1.DeleteProjectRequest]) (*connect.Response[v1.DeleteProjectResponse], error)
	// 往项目里加一个容器（只保存，不部署）。
	AddContainer(context.Context, *connect.Request[v1.AddContainerRequest]) (*connect.Response[v1.Project], error)
	// 把节点上一个现有的 compose 目录导入为容器组，数据留在原处（见 docs/agent.md#现有目录）。只保存，不部署；
	// 部署时停掉目录里原来运行的容器，由面板接管。只有管理员能用，要先确认身份。
	ImportComposeDir(context.Context, *connect.Request[v1.ImportComposeDirRequest]) (*connect.Response[v1.Project], error)
	// 删除容器：停止并删除它，目录默认保留。
	DeleteContainer(context.Context, *connect.Request[v1.DeleteContainerApiRequest]) (*connect.Response[v1.Project], error)
	// 手动启动、停止或重启容器：不改配置，不生成版本。设置了顶替的容器不能停止。
	ControlContainer(context.Context, *connect.Request[v1.ControlContainerRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 手动启动、停止或重启容器组里的一个服务，其他服务不动。规则和 ControlContainer 一样。
	ControlService(context.Context, *connect.Request[v1.ControlServiceRequest], *connect.ServerStream[v1.DeployEvent]) error
	SaveDraft(context.Context, *connect.Request[v1.SaveDraftRequest]) (*connect.Response[v1.Project], error)
	DiscardDraft(context.Context, *connect.Request[v1.ContainerRevisionRef]) (*connect.Response[v1.Project], error)
	// 部署一个或多个容器：有草稿的容器把草稿记为新版本，没有的重新部署最新版本。
	// 按依赖顺序逐个部署，某个失败就停下。整次部署记一条部署记录。
	Deploy(context.Context, *connect.Request[v1.DeployRequest], *connect.ServerStream[v1.DeployEvent]) error
	ListVersions(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListVersionsResponse], error)
	// 这个容器最近的事件：操作和告警，新的在前。所有角色都能看；只读角色看不到失败的详细信息。
	ListContainerEvents(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListActivityResponse], error)
	// 项目的活动记录（操作和告警），新的在前，可以按容器、只看失败的筛选，用 before 翻页。
	ListProjectEvents(context.Context, *connect.Request[v1.ListProjectEventsRequest]) (*connect.Response[v1.ListActivityResponse], error)
	// 回滚容器到某个版本：用它的配置、文件和镜像生成这个容器的新版本并部署，可选同时恢复数据。
	Rollback(context.Context, *connect.Request[v1.RollbackRequest], *connect.ServerStream[v1.DeployEvent]) error
	ListDeployments(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.ListDeploymentsResponse], error)
	// 回到某次部署时的状态：版本不一样的容器都回滚到那次记录的版本，作为一次一起部署执行。
	RestoreDeployment(context.Context, *connect.Request[v1.RestoreDeploymentRequest], *connect.ServerStream[v1.DeployEvent]) error
	StreamLogs(context.Context, *connect.Request[v1.StreamLogsApiRequest], *connect.ServerStream[v1.LogLine]) error
	// 端口映射，立即生效。
	SaveRoute(context.Context, *connect.Request[v1.SaveRouteRequest]) (*connect.Response[v1.Project], error)
	DeleteRoute(context.Context, *connect.Request[v1.DeleteRouteRequest]) (*connect.Response[v1.Project], error)
	// 检查映射绑定的域名：是否解析到入口节点、证书状态。映射可以还没保存（编辑时用）。
	CheckDomains(context.Context, *connect.Request[v1.CheckDomainsRequest]) (*connect.Response[v1.CheckDomainsResponse], error)
	// 让入口节点立刻重新申请证书，不用等 Caddy 的下一次自动重试。
	RetryDomainCert(context.Context, *connect.Request[v1.RetryDomainCertRequest]) (*connect.Response[v1.RetryDomainCertResponse], error)
	// 备份节点、迁移（按容器，见 docs/failover.md）。
	// 设置容器的备份节点（整个列表，为空表示取消），见 docs/snapshot.md#异地副本。
	SetBackupNodes(context.Context, *connect.Request[v1.SetBackupNodesRequest]) (*connect.Response[v1.Project], error)
	// 修改容器的显示名称（为空表示改回显示容器名）。容器名本身不能改。
	SetContainerDisplayName(context.Context, *connect.Request[v1.SetContainerDisplayNameRequest]) (*connect.Response[v1.Project], error)
	// 容器单独设置告警规则（rules 为空表示改回用项目的）。
	SetContainerAlertRules(context.Context, *connect.Request[v1.SetContainerAlertRulesRequest]) (*connect.Response[v1.Project], error)
	// 容器单独设置定时快照计划，schedule 为空时改回用项目的。
	SetContainerSnapshotSchedule(context.Context, *connect.Request[v1.SetContainerSnapshotScheduleRequest]) (*connect.Response[v1.Project], error)
	// 立即同步到备份节点（node_id 为空时依次同步到所有备份节点）。节点支持时只开始同步就返回，进度和结果看 Container.backups；
	// 旧版本的节点同步完才有结果，面板在后台等。
	SyncBackup(context.Context, *connect.Request[v1.BackupNodeRef]) (*connect.Response[v1.Project], error)
	// 停止正在进行的同步（node_id 为空时停止到所有备份节点的）。已经传完的文件留在备份节点上，下次接着传。
	StopBackupSync(context.Context, *connect.Request[v1.BackupNodeRef]) (*connect.Response[v1.Project], error)
	// 备份节点上副本里的快照（node_id 为空时用第一个备份节点）。
	ListBackupSnapshots(context.Context, *connect.Request[v1.BackupNodeRef]) (*connect.Response[v1.ListSnapshotsResponse], error)
	// 修改容器在一个备份节点上的副本存放位置，把副本移过去（dir 为空表示改回节点的默认目录）。只有管理员能用，要先做高权限确认。
	SetBackupReplicaDir(context.Context, *connect.Request[v1.SetBackupReplicaDirRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 原节点离线时，在备份节点上把容器恢复出来。
	RestoreFromBackup(context.Context, *connect.Request[v1.RestoreFromBackupRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 把容器迁移到另一个节点（两个节点都在线），不丢数据。
	MigrateContainer(context.Context, *connect.Request[v1.MoveContainerRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 原节点离线又没有副本时，把容器换到另一个节点重新部署（数据和旧版本的文件都没有）。
	RedeployElsewhere(context.Context, *connect.Request[v1.MoveContainerRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 顶替（按容器，见 docs/failover.md#节点故障指定顶替节点）。
	SetFailover(context.Context, *connect.Request[v1.SetFailoverApiRequest]) (*connect.Response[v1.Project], error)
	ClearFailover(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.Project], error)
	// 更换见证人，顶替照常进行。
	ChangeWitness(context.Context, *connect.Request[v1.ChangeWitnessRequest]) (*connect.Response[v1.Project], error)
	// 有状态容器的所在节点失联时，确认由热备顶替。
	ConfirmTakeover(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.Project], error)
	// 项目连接（双向，立即生效）：连上以后两个项目的容器用"容器.网络名"访问对方。
	ConnectProject(context.Context, *connect.Request[v1.ConnectProjectRequest]) (*connect.Response[v1.Project], error)
	DisconnectProject(context.Context, *connect.Request[v1.ConnectProjectRequest]) (*connect.Response[v1.Project], error)
	// 容器的存储：data/、命名 volume，大小和挂载位置。
	ListVolumes(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListVolumesResponse], error)
	// 卷里的文件。只读角色不能用；下载和上传走 /api/volume-file。
	ListVolumeFiles(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.ListVolumeFilesResponse], error)
	DeleteVolumeFile(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	CreateVolumeDir(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	RestoreVolumeFile(context.Context, *connect.Request[v1.VolumeFileRef]) (*connect.Response[v1.VolumeFileOpResponse], error)
	// 同一个卷里的改名、移动、复制，压缩和解压。长操作流式返回进度。
	RenameVolumeFile(context.Context, *connect.Request[v1.VolumeTransferRequest]) (*connect.Response[v1.FileOpResult], error)
	MoveVolumeFiles(context.Context, *connect.Request[v1.VolumeTransferRequest], *connect.ServerStream[v1.FileOpEvent]) error
	CopyVolumeFiles(context.Context, *connect.Request[v1.VolumeTransferRequest], *connect.ServerStream[v1.FileOpEvent]) error
	CompressVolumeFiles(context.Context, *connect.Request[v1.VolumeCompressRequest], *connect.ServerStream[v1.FileOpEvent]) error
	ExtractVolumeFile(context.Context, *connect.Request[v1.VolumeExtractRequest], *connect.ServerStream[v1.FileOpEvent]) error
	ListVolumeDirSizes(context.Context, *connect.Request[v1.VolumeDirSizesRequest]) (*connect.Response[v1.DirSizesResponse], error)
	// 快照（按容器）。
	ListSnapshots(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.ListSnapshotsResponse], error)
	// 给容器做一份手动快照；container 为空时给项目里所有部署过的容器各做一份。
	CreateSnapshot(context.Context, *connect.Request[v1.ContainerRef], *connect.ServerStream[v1.DeployEvent]) error
	RestoreSnapshot(context.Context, *connect.Request[v1.RestoreSnapshotRequest], *connect.ServerStream[v1.DeployEvent]) error
	// 删除一份定时、手动或部署前快照。版本文件不能删（回滚要用）。
	DeleteSnapshot(context.Context, *connect.Request[v1.RestoreSnapshotRequest]) (*connect.Response[v1.ListSnapshotsResponse], error)
	// 面板保存的容器快照仓库密码。节点坏了只剩备份文件时，用 kopia 打开仓库要用到。
	GetBackupKey(context.Context, *connect.Request[v1.ContainerRef]) (*connect.Response[v1.GetBackupKeyResponse], error)
	// 私有仓库认证：每个项目自己的登录信息。
	ListRegistries(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.RegistriesResponse], error)
	LoginRegistry(context.Context, *connect.Request[v1.LoginRegistryApiRequest]) (*connect.Response[v1.RegistriesResponse], error)
	LogoutRegistry(context.Context, *connect.Request[v1.LogoutRegistryRequest]) (*connect.Response[v1.RegistriesResponse], error)
	// 立即检查项目的镜像有没有新版本。
	CheckImages(context.Context, *connect.Request[v1.ProjectRef]) (*connect.Response[v1.CheckImagesResponse], error)
}

